package com.termux.x11;
import android.app.Application;import android.os.Bundle;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import org.robolectric.util.ReflectionHelpers;import java.lang.reflect.*;import java.util.*;import java.util.concurrent.ExecutorService;import static org.junit.Assert.*;
/** Invokes only state/ownership commands. No service lifecycle or native children. */
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,application=Application.class)
public class X11ExistingDesktopTest {
 X11Service service;Method command;
 @Before public void setup()throws Exception{service=Robolectric.buildService(X11Service.class).get();command=X11Service.class.getDeclaredMethod("command",Bundle.class);command.setAccessible(true);ReflectionHelpers.setField(service,"target","debian");ReflectionHelpers.setField(service,"started",true);ReflectionHelpers.setField(service,"phase","running");ReflectionHelpers.setField(service,"desktopOwner","first:h1");Set<String> owners=ReflectionHelpers.getField(service,"desktopUsers");owners.add("first:h1");}
 @After public void close(){((ExecutorService)ReflectionHelpers.getField(service,"worker")).shutdownNow();}
 Bundle query(String target,String owner){Bundle q=X11Remote.command("open-existing");q.putString("target",target);q.putString("owner",owner);return q;}
 @Test public void opensExistingWithAdditionalOwnerWithoutChangingConfigOrStartingWorker()throws Exception{Bundle before=service.snapshot();Bundle after=(Bundle)command.invoke(service,query("debian","second:h2"));assertEquals(new HashSet<>(Arrays.asList("first:h1","second:h2")),new HashSet<>(after.getStringArrayList("desktopOwners")));for(String key:new String[]{"phase","target","renderer","desktop"})assertEquals(before.get(key),after.get(key));assertEquals(before.getBoolean("ready"),after.getBoolean("ready"));assertNull(ReflectionHelpers.getField(service,"runtime"));command.invoke(service,query("debian","second:h2"));assertEquals(2,service.snapshot().getStringArrayList("desktopOwners").size());}
 @Test public void staleStoppedRetiringWrongEnvironmentAndInvalidOwnerFailClosed()throws Exception{for(int n=0;n<5;n++){ReflectionHelpers.setField(service,"started",n!=0);ReflectionHelpers.setField(service,"stopping",n==1);ReflectionHelpers.setField(service,"retiring",n==2);try{command.invoke(service,query(n==3?"ubuntu":"debian",n==4?"":"second:h2"));fail("must reject "+n);}catch(InvocationTargetException expected){assertTrue(expected.getCause() instanceof IllegalStateException||expected.getCause() instanceof IllegalArgumentException);}assertEquals(Collections.singletonList("first:h1"),service.snapshot().getStringArrayList("desktopOwners"));assertNull(ReflectionHelpers.getField(service,"runtime"));}}
}
